+export function parseImportCsv(text: string): Array<{ line: number; row: LegacyRow }> {
+  const [headerRec, ...body] = parseCsv(text);
+  if (!headerRec) return [];
+  const header = headerRec.cells.map((h) => h.trim().toLowerCase());
+
